  {
    id: "python-rozszerzenie-3",
    title: "Rozszerzenie – Quiz 1",
    level: "rozszerzony",
    questions: 30,
    content: "Opis quizu",
  },
];


function App({ quizzes }) {
  return (
    <Routes>
      <Route path="/" element={<StartQuiz listQuiz={quizzes} />} />
      {/* <Route path="/quiz/:id" element={<Quiz quizzes={quizzes} />} /> */}
    </Routes>
  );
}

export default App;
